await expect.poll(() => page.evaluate(() => !!window.__CHAR__?.rot), { timeout: 5_000, message: 'turned facing never arrived over the wire' }).toBe(true);
const cRotD = (await page.evaluate(() => window.__CHAR__!.rot)) as Quat;
```

